'use strict'

const { EventEmitter } = require('events')
const net = require('net')

const { parse, serialize } = require('pg-protocol')
const { getStream, getSecureStream } = require('./stream')

const flushBuffer = serialize.flush()
const syncBuffer = serialize.sync()
const endBuffer = serialize.end()

class Connection extends EventEmitter {
  constructor(config = {}) {
    super()

    this.stream = config.stream || getStream(config.ssl)
    if (typeof this.stream === 'function') {
      this.stream = this.stream(config)
    }

    this._keepAlive = config.keepAlive
    this._keepAliveInitialDelayMillis = config.keepAliveInitialDelayMillis
    this.parsedStatements = {}
    this.ssl = config.ssl || false
    this._ending = false
    this._emitMessage = false
    this._connecting = false

    this.on('newListener', (eventName) => {
      if (eventName === 'message') {
        this._emitMessage = true
      }
    })
  }

  connect(port, host) {
    this._connecting = true
    this.stream.setNoDelay(true)
    this.stream.connect(port, host)

    this.stream.once('connect', () => {
      if (this._keepAlive) {
        this.stream.setKeepAlive(true, this._keepAliveInitialDelayMillis)
      }
      this.emit('connect')
    })

    const reportStreamError = (error) => {
      if (this._ending && (error.code === 'ECONNRESET' || error.code === 'EPIPE')) {
        return
      }
      this.emit('error', error)
    }

    this.stream.on('error', reportStreamError)

    this.stream.on('close', () => {
      this.emit('end')
    })

    if (!this.ssl) {
      return this.attachListeners(this.stream)
    }

    this.stream.once('data', (buffer) => {
      const responseCode = buffer.toString('utf8')
      switch (responseCode) {
        case 'S':
          break
        case 'N':
          this.stream.end()
          return this.emit('error', new Error('The server does not support SSL connections'))
        default:
          this.stream.end()
          return this.emit('error', new Error('There was an error establishing an SSL connection'))
      }

      const options = { socket: this.stream }

      if (this.ssl !== true) {
        Object.assign(options, this.ssl)
      }

      if (host && net.isIP && net.isIP(host) === 0) {
        options.servername = host
      }

      try {
        this.stream = getSecureStream(options)
      } catch (err) {
        return this.emit('error', err)
      }

      this.attachListeners(this.stream)
      this.stream.on('error', reportStreamError)
      this.emit('sslconnect')
    })
  }

  attachListeners(stream) {
    parse(stream, (msg) => {
      const eventName = msg.name === 'error' ? 'errorMessage' : msg.name
      if (this._emitMessage) {
        this.emit('message', msg)
      }
      this.emit(eventName, msg)
    })
  }

  requestSsl() {
    this.stream.write(serialize.requestSsl())
  }

  startup(config) {
    this.stream.write(serialize.startup(config))
  }

  cancel(processID, secretKey) {
    this._send(serialize.cancel(processID, secretKey))
  }

  password(password) {
    this._send(serialize.password(password))
  }

  sendSASLInitialResponseMessage(mechanism, initialResponse) {
    this._send(serialize.sendSASLInitialResponseMessage(mechanism, initialResponse))
  }

  sendSCRAMClientFinalMessage(additionalData) {
    this._send(serialize.sendSCRAMClientFinalMessage(additionalData))
  }

  _send(buffer) {
    if (!this.stream.writable) {
      return false
    }
    return this.stream.write(buffer)
  }

  query(text) {
    this._send(serialize.query(text))
  }

  parse(query) {
    this._send(serialize.parse(query))
  }

  bind(config) {
    this._send(serialize.bind(config))
  }

  execute(config) {
    this._send(serialize.execute(config))
  }

  flush() {
    if (this.stream.writable) {
      this.stream.write(flushBuffer)
    }
  }

  sync() {
    this._ending = true
    this._send(syncBuffer)
  }

  ref() {
    this.stream.ref()
  }

  unref() {
    this.stream.unref()
  }

  end() {
    this._ending = true
    if (!this._connecting || !this.stream.writable) {
      this.stream.end()
      return
    }
    return this.stream.write(endBuffer, () => {
      this.stream.end()
    })
  }

  close(msg) {
    this._send(serialize.close(msg))
  }

  describe(msg) {
    this._send(serialize.describe(msg))
  }

  sendCopyFromChunk(chunk) {
    this._send(serialize.copyData(chunk))
  }

  endCopyFrom() {
    this._send(serialize.copyDone())
  }

  sendCopyFail(msg) {
    this._send(serialize.copyFail(msg))
  }
}

module.exports = Connection